// Generated by Step 3
package com.example.kyrgyzkeyboard.keyboard

object EnglishKeyboardLayouts {

    fun letterLayout(shifted: Boolean): List<KeyboardRow> {
        val letters = if (shifted) {
            listOf("Q", "W", "E", "R", "T", "Y", "U", "I", "O", "P",
                   "A", "S", "D", "F", "G", "H", "J", "K", "L",
                   "Z", "X", "C", "V", "B", "N", "M")
        } else {
            listOf("q", "w", "e", "r", "t", "y", "u", "i", "o", "p",
                   "a", "s", "d", "f", "g", "h", "j", "k", "l",
                   "z", "x", "c", "v", "b", "n", "m")
        }

        return listOf(
            // Row 1: 快捷数字键 + Q-P
            KeyboardRow(listOf(
                KyrgyzKey.switchDigital("123"),
                KyrgyzKey.letter(letters[0]), KyrgyzKey.letter(letters[1]), KyrgyzKey.letter(letters[2]),
                KyrgyzKey.letter(letters[3]), KyrgyzKey.letter(letters[4]), KyrgyzKey.letter(letters[5]),
                KyrgyzKey.letter(letters[6]), KyrgyzKey.letter(letters[7]), KyrgyzKey.letter(letters[8]),
                KyrgyzKey.letter(letters[9])
            )),
            // Row 2: A-L
            KeyboardRow(listOf(
                KyrgyzKey.letter(letters[10]), KyrgyzKey.letter(letters[11]), KyrgyzKey.letter(letters[12]),
                KyrgyzKey.letter(letters[13]), KyrgyzKey.letter(letters[14]), KyrgyzKey.letter(letters[15]),
                KyrgyzKey.letter(letters[16]), KyrgyzKey.letter(letters[17]), KyrgyzKey.letter(letters[18])
            )),
            // Row 3: Shift + Z-M + Backspace
            KeyboardRow(listOf(
                KyrgyzKey.shift(),
                KyrgyzKey.letter(letters[19]), KyrgyzKey.letter(letters[20]), KyrgyzKey.letter(letters[21]),
                KyrgyzKey.letter(letters[22]), KyrgyzKey.letter(letters[23]), KyrgyzKey.letter(letters[24]),
                KyrgyzKey.letter(letters[25]), KyrgyzKey.backspace()
            )),
            // Row 4: 功能键
            KeyboardRow(listOf(
                KyrgyzKey.switchLayout("符号"),
                KyrgyzKey.switchLanguage("英"),
                KyrgyzKey.symbol(","),
                KyrgyzKey.space(),
                KyrgyzKey.symbol("."),
                KyrgyzKey.newline()
            ))
        )
    }
}
